      "role": "1. 算法类岗位\n核心聚焦：原生多模态、强化学习、训练算法、多智能体、推理、模型架构、物理智能、大模型评测、医疗大模型算法、Agent 智能算法等\n2. 研发类岗位\n核心聚焦：大规模分布式训练框架、高性能计算、AI 系统与架构、基础架构、前后端开发、GPU 平台研发、云原生 AI 工程等\n3. 产品类岗位\n核心聚焦：AI 产品规划、解决方案设计、大模型落地产品、行业场景产品落地\n4. 运营类岗位\n核心聚焦：生态运营、科学智能 AI4S 战略研究、技术交流活动运营、行业生态对接\n5. 项目管理类岗位\n核心聚焦：跨团队重大 AI 项目统筹、项目进度管控、跨领域协同管理\n6. 职能类岗位\n核心聚焦：人力行政、党务群团、综合行政、数据战略分析、品牌宣传、行政后勤等",
