      "searchText": "2027届内推暑期实习信息\n上海人工智能实验室\n1. 算法类岗位\n核心聚焦：原生多模态、强化学习、训练算法、多智能体、推理、模型架构、物理智能、大模型评测、医疗大模型算法、agent 智能算法等\n2. 研发类岗位\n核心聚焦：大规模分布式训练框架、高性能计算、ai 系统与架构、基础架构、前后端开发、gpu 平台研发、云原生 ai 工程等\n3. 产品类岗位\n核心聚焦：ai 产品规划、解决方案设计、大模型落地产品、行业场景产品落地\n4. 运营类岗位\n核心聚焦：生态运营、科学智能 ai4s 战略研究、技术交流活动运营、行业生态对接\n5. 项目管理类岗位\n核心聚焦：跨团队重大 ai 项目统筹、项目进度管控、跨领域协同管理\n6. 职能类岗位\n核心聚焦：人力行政、党务群团、综合行政、数据战略分析、品牌宣传、行政后勤等\n\n上海\n人工智能\n27届暑期实习\n\n上海人工智能实验室2027届留用实习开启\n\n上海人工智能实验室是我国人工智能领域的新型科研机构，开展战略性、原创性、前瞻性的科学研究与技术攻关，突破人工智能的重要基础理论和关键核心技术，打造“突破型、引领型、平台型”一体化的大型综合性研究基地，支撑我国人工智能产业实现跨越式发展，目标建成国际一流的人工智能实验室，成为享誉全球的人工智能原创理论和技术的策源地。\n\n✅ 投递 0 限制：简历可多次投递，心仪岗位大胆冲！\n✅ 职位，赛道超丰富，细分方向任你选！\n✅ 顶级科研平台与资源：超大规模算力集群，pb级数据，亿级研发投入！\n✅ 清晰的职业发展通道：由实验室出题，链接顶尖高校、科研机构和行业企业\nhttps://jsj.top/f/jrztj8?x_field_1=pph\nhttps://jsj.top/f/jrztj8?x_field_1=pph\n上海\n1. 算法类岗位\n核心聚焦：原生多模态、强化学习、训练算法、多智能体、推理、模型架构、物理智能、大模型评测、医疗大模型算法、agent 智能算法等\n2. 研发类岗位\n核心聚焦：大规模分布式训练框架、高性能计算、ai 系统与架构、基础架构、前后端开发、gpu 平台研发、云原生 ai 工程等\n3. 产品类岗位\n核心聚焦：ai 产品规划、解决方案设计、大模型落地产品、行业场景产品落地\n4. 运营类岗位\n核心聚焦：生态运营、科学智能 ai4s 战略研究、技术交流活动运营、行业生态对接\n5. 项目管理类岗位\n核心聚焦：跨团队重大 ai 项目统筹、项目进度管控、跨领域协同管理\n6. 职能类岗位\n核心聚焦：人力行政、党务群团、综合行政、数据战略分析、品牌宣传、行政后勤等\n人工智能\n上海人工智能实验室\n直接复制内推链接至浏览器即可投递\n27届暑期实习"
