      "searchText": "2026届春招内推\n图拉斯（蓝禾）\n1.运营岗位：天猫运营管培生、亚马逊运营管培生、京东运营管培生、抖音运营管培生、拼多多运营管培生；\n2.设计类：电商平面设计师、三维建模渲染师；\n3.营销类：国内品牌营销专员；\n4.职能类：财务专员\n\n深圳\n互联网、3c\n26届春招\ndzjfxuj\n我们是图拉斯一家集产品、设计、研发、品牌、营销与大数据于一体的创新型科技公司，全球员工超3200人，业务覆盖148+国家和地区！\n【base：深圳市龙华区】\n✅ 推荐岗位：\n🎖国内电商运营（不限专业！）：天猫运营管培生、京东运营管培生、抖音运营管培生、拼多多运营管培生、小红书运营管培生；\n🎖职能类：项目专员、财务专员、采购专员、质量工程师、品类运营专员；\n🎖设计类：天猫电商平面设计师、京东电商平面设计师；\n🎖渲染类：天猫三维建模渲染师；\n🎖营销类：剪辑师、摄影师、电商主播、短视频编导；\n🎖产品类：产品储备干部；\n\n✅ 我们提供：\n▪ 年薪10w-20w+，上不封顶\n▪ 电商/设计/营销/研发/职能等多类岗位\n▪ 不限专业！欢迎跨学科背景的你！\n▪ 一对一导师制 + 专业/管理双通道发展\n▪ 健身房、食堂、兴趣部落、团建旅游、每月主题生日会…\n【内推链接】https://lanhevip.jobs.feishu.cn/s/wa4pycokbd4\n互联网、3c\n图拉斯（蓝禾）\ndzjfxuj\n26届春招\n深圳\n1.运营岗位：天猫运营管培生、亚马逊运营管培生、京东运营管培生、抖音运营管培生、拼多多运营管培生；\n2.设计类：电商平面设计师、三维建模渲染师；\n3.营销类：国内品牌营销专员；\n4.职能类：财务专员\nhttps://lanhevip.jobs.feishu.cn/s/wa4pycokbd4"
