      "searchText": "2027届内推暑期实习信息\n阿里系-灵犀互娱\n策划 | 技术 | 美术 | 产品 | 运营 | 营销 | 项目管理 | 服务体验 | 多种类型岗位等级投递！\n\n广州/上海/北京\n游戏\n27届暑期实习\n1vp830\n策划 | 技术 | 美术 | 产品 | 运营 | 营销 | 项目管理 | 服务体验 | 多种类型岗位等级投递！\n27届暑期实习\n👏阿里巴巴灵犀互娱2027届实习生招聘正式启动！\n\n与顶尖团队共造下一个爆款，你准备好了吗？🔥\n\n✨ 为什么选择阿里巴巴灵犀互娱？ \n✅ 资深导师指导！策划岗更有机会专属制作人直带，大牛手把手带你从0到1做游戏 ！\n✅ 玩出热爱的团队基因！拒绝内卷，只招真正热爱游戏的纯粹玩家（福利超多！） \n✅ 全赛道创意自由区！多赛道创意孵化机制，助力萌新们敢想敢为\n\n👾面向人群：\n暑期实习（2027届）:2026年11月-2027年10月期间毕业的海内外同学\n应届生补招（2026届）：2025年11月-2026年10月期间毕业的海内外同学\n\n🕹岗位：策划 | 技术 | 美术 | 产品 | 运营 | 营销 | 项目管理 | 服务体验 | 多种类型岗位等级投递！\n\n🕹地点：广州/上海/北京\n\n⚡ 内推福利：输入内推码【1vp830】，简历优先筛选！面试快人一步！ \n【内推链接】\nhttps://campus-talent.alibaba.com/campus/position?campussharecode=xcul%2foytthxxzdp6lqccs%2fxydyjip2u52xsutnofcms%3d&batchid=100000540002&filterparams=%7b%22customdept%22%3a%5b%22yqnhyu%22%5d%7d\n竞争激烈，现在投递=提前锁定offer！\n1vp830\n阿里系-灵犀互娱\nhttps://campus-talent.alibaba.com/campus/position?campussharecode=xcul%2foytthxxzdp6lqccs%2fxydyjip2u52xsutnofcms%3d&batchid=100000540002&filterparams=%7b%22customdept%22%3a%5b%22yqnhyu%22%5d%7d\n广州/上海/北京\n游戏"
