      "note": "库洛游戏2026届春节校园招聘开启\n\n【公司简介】库洛游戏(KURO GAMES)诞生于2014年，总部位于广州，致力打造优质的互动娱乐体验.目前，库洛游戏通过游戏研发及长线运营、全球化发行及原创IP孵化实现自我挑战和成长，旗下在营产品包括《战双帕弥什》、《鸣潮》以及游戏IP衍生产品，海外发行覆盖日韩、东南亚、欧美等国家或区域。\n\n【招聘岗位】十大职类，超过40个具体岗位。包括策划类、美术类、技术类、营销类、职能类、运营类、语言类、项管类、视频类、音频类,专业不限。\n\n【工作地点】广州、上海\n\n【薪酬福利】行业竞争力的薪酬，每年两次的薪酬回顾机会，能力成长及时兑现;五险一金，补充商业医疗保险。新人礼品，司龄纪念品；部分传统节日礼盒掉落，年会阳光普照礼品；工作日晚餐供应，不定时掉落下午茶；首年即享法定年假，带薪福利假。\n\n【内推链接】https://kurogame.jobs.feishu.cn/s/q47AW8nWaVc\n\n【内推码】WJDGYQ5",
