      "searchText": "2026届春招内推\n基恩士\n销售工程师\n\n北京，天津，大连，青岛，南京，无锡，苏州，昆山，合肥，上海，杭州，宁波，武汉，重庆，成都，广州，东莞，深圳，厦门，中山，济南，长春，长沙，西安\n外企\n26届秋招正式批\nevvg8j\n基恩士\n外企\nevvg8j\n销售工程师\n北京，天津，大连，青岛，南京，无锡，苏州，昆山，合肥，上海，杭州，宁波，武汉，重庆，成都，广州，东莞，深圳，厦门，中山，济南，长春，长沙，西安\n26届秋招正式批\nhttps://keyence.zhiye.com/campus/jobs\n基恩士2026秋招招聘销售工程师（不限专业）\n\n关于我们：日本上市公司市值top5，连续8年入选福布斯“全球最具创新力企业”100强榜单\n\n工作内容：\n1、顾问式销售，在所负责区域范围内推广、销售基恩士产品，帮助客户解决问题\n2、直接对应最终用户，了解客户显在和潜在需求（b2b销售）\n3、分析所负责区域的行业动态并制定相应的战略计划，实现指定区域销售业绩最大化\n\n薪资福利\n1、有竞争力的薪资待遇：第一年18-22万元，第二年23-31万元\n2、每半年调薪&升职机会、带薪培训、周末双休、带薪假、无酒桌文化，更有外出专车与司机、补充商业保险、节假日福利补贴等员工福利等\n\n工作地点：北京，天津，大连，青岛，南京，无锡，苏州，昆山，合肥，上海，杭州，宁波，武汉，重庆，成都，广州，东莞，深圳，厦门，中山，济南，长春，长沙，西安\n\n网申/投递链接：https://keyence.zhiye.com/campus/detail?jobadid=16ec0fc7-11af-491f-9027-9d8c05b988bd&shareid=39cd2588-203f-4959-b3df-fdd8d7712b0e&sharesource=2"
