      "note": "国内首家互联网保险上市公司｜众安保险2026届秋招正式启动\n\n关于我们：众安保险是中国首家互联网保险公司，于2013年11月6日揭牌开业，2017年9月28日在香港联交所主板上市。众安总部位于上海，不设任何分支机构，完全通过互联网展业。由“保险+科技”双引擎驱动，众安专注于应用新技术重塑保险价值链，围绕健康、数字生活、消费金融、汽车四大生态，以科技服务新生代，为其提供个性化、定制化、智能化的新保险。截至2023年中，众安服务超过5亿用户，累计出具约574亿张保单。\n\n招聘岗位：网络工程、SRE工程师、财务核算专员、核保专员、理赔专员、用户运营专员、互联网产品经理、后端开发工程师、算法工程师、数据分析师、测试开发工程师、战略企划专员、HR\n\n工作地点：深圳、上海\n\n投递链接：https://app.mokahr.com/m/campus_apply/zhongan/71908?recommendCode=DSx39NYV&hash=%23%2Fjobs#/jobs\n\n内推码：DSx39NYV（简历优先筛选，加速流程推进）",
