      "note": "机器人上市企业【越疆机器人2026届全球校园招聘】正在火热进行中！\n【招聘岗位】\n①算法类：算法研究员（博士方向）、算法工程师（强化学习/运动规划/路径规划/动力学/SLAM/多模态/具身模型等不同方向）；\n②研发类：伺服开发工程师、测试工程师、机械结构工程师、软件工程师、产品经理、项目助理、嵌入式应用工程师、嵌入式软件工程师（ROS/C++/MCU方向）；\n③营销类：国内销售管培生、Overseas Sales、品牌营销专员；\n④技术类：国内技术支持工程师、Technical Support & Trainer，生产质量/成本/现场工程师；\n⑤职能类：产品营销专员、人力资源专员\n【薪酬福利】\n①福利关怀：六险一金、大牛导师、租房补贴、年终奖金、年度体检、员工俱乐部与健身房、各类补贴、未来股权激励等。\n②年度薪酬：算法博士类百万年薪以上、算法硕士类40W-80W、研发类25-45W、非研发类18-30W。\n【内推链接】\nhttps://dobot.zhiye.com/campus/jobs?shareId=64062a8a-daba-439a-8730-cb71b151adaf&shareSource=2&qr=1\n🔥🔥🔥【加上内推码，快人一步】:EVKMAR",
