      "note": "舜宇集团2026届校园招聘启动——中国制造业500强！\n\n理工科背景的朋友们请积极投递！！\n提供住宿/住房补贴+工作餐\n13薪+年终奖+EVA+年度调薪+五险一金，双休\n专业需求：机械、自动化、电子、电气、通信、控制、测控、计算机、软件、物理、光学、外语、人力资源、财经等专业\n（各理工科专业均有可投递的岗位！！）\n\n【我们是】舜宇集团是全球领先的综合光学产品制造商，公司成立于1984年，2007年成为第一家在香港联交所主板上市的国内光学企业。连续多年入围《财富》中国500强排行榜。行业成就：车载镜头、手机摄像模组、手机镜头市占率全球第一。\n\n【热招岗位】\n结构设计、光学设计、电子设计、软件开发、图像算法处理、工艺技术、销售、市场开发、质量管理、人力资源、财经等1000+岗位需求\n\n【主要工作地点】宁波余姚、广东中山、浙江杭州、上海\n\n【内推投递链接】\nhttps://app.mokahr.com/m/campus_apply/sunnyoptical/45602?recommendCode=DSxN3X5z&hash=%23%2Fjobs\n【内推码】DSxN3X5z",
