      "searchText": "2026届春招内推\n科华集团\n英才计划、研发类、营销类、供应链类、职能类\n\n研发基地：厦门、漳州、深圳\n国内业务：全国各省会城市\n国际业务：厦门、海外各区域\n新能源\n26届秋招正式批\ndshqgrku\n研发基地：厦门、漳州、深圳\n国内业务：全国各省会城市\n国际业务：厦门、海外各区域\n🎉科华集团2026届校园招聘正式启动\n竭诚欢迎各位卓越青年加入我们！\n\n👏科华集团成立于1988年，近40年来深耕电力电子与数字技术创新，形成数据中心、高端电源、清洁能源三大业务矩阵。公司以“ai+数字能源”为核心，为互联网、金融、交通、石化、通信、电力、政府、医疗、科研教育等行业提供智慧电能及智算解决方案，共建数字低碳未来。\n🏆【科华荣誉】\n📌2024中国ups及微模块数据中心市场份额no.1\n📌2024中国ups市场份额no.1\n📌2024中国企业全球储能pcs出货量no.1\n📌连续10年全球新能源企业500强\n📌2024中国充换电行业十大影响力品牌\n🗳【五大热招岗位类别】\n英才计划、研发类、营销类、供应链类、职能类\n📚【专业要求】\n电力电子类、电气工程类、自动化类、控制工程类、能源与动力工程类、新能源类、储能类等\n📍【工作地点】\n研发基地：厦门、漳州、深圳\n国内业务：全国各省会城市\n国际业务：厦门、海外各区域\n内推链接：https://app.mokahr.com/m/campus_apply/kehua/92510?recommendcode=dshqgrku&hash=%23%2fjobs#/jobs\n💡科华专属校园大使内推码：dshqgrku\n新能源\n26届秋招正式批\nhttps://app.mokahr.com/m/campus_apply/kehua/92510?recommendcode=dshqgrku&hash=%23%2fjobs#/jobs\ndshqgrku\n英才计划、研发类、营销类、供应链类、职能类\n科华集团"
