      "note": "搜狐畅游26届秋招正式批开启 25&26届均可投递\n\n公司介绍：搜狐畅游是中国领先的互联网游戏开发和运营商，搜狐全资子公司 \n\n面向对象：2026届毕业生（2025.9-2026.8毕业），兼收2025届无正式工作经验的毕业生\n\n招聘岗位：游戏策划、游戏程序开发、游戏美术、游戏运营、平台技术、平台业务（AI产品经理、项目管理、战略研究）、平台职能8大类别（每个同学最多可以投递两个岗位，优先处理第一志愿） \n\n福利待遇：有竞争力的薪资、七险一金、18天带薪年假、餐费补贴、绩效奖金、企业滴滴、24h健身房、北京落户机会、校招培养发展体系 \n\n网申链接：https://app.mokahr.com/m/campus_apply/cyou-inc/42233?recommendCode=DSUcS4RK&hash=%23%2Fjobs\n内推链接：DSUcS4RK",
