      "note": "25-26届均可投｜嘉士伯中国2026届秋招正式启动\n\n关于我们：嘉士伯集团是全球三大啤酒公司之一，创建于1847年，总部位于丹麦首都哥本哈根，旗下140多个品牌畅销于全球150个市场。嘉士伯中国拥有“本地品牌+国际品牌”的品牌组合。国际品牌有嘉士伯、乐堡、1664、格林堡、布鲁克林、夏日纷等，本地品牌有乌苏、重庆、山城、西夏、大理、风花雪月、京A等，能够满足消费者在不同场景的消费需求。中国已发展成为嘉士伯集团在全球最大的市场。\n\n三大招聘项目：商务管培生（重磅首发）、供应链管培生、职能管培生\n\n1. 商务管培生：培养具有全渠道销售能力，或新营销和数字化思维的销售领导者，base成都/重庆/贵阳/长沙/广州/厦门/常州/北京/乌鲁木齐/银川/兰州/昆明/大理/曲靖/丽江/西双版纳等\n2. 供应链管培生：有工程设备管理（base常州/惠州/乌鲁木齐/伊宁/宜宾）、包装运营管理（base常州/成都/滁州/佛山/惠州/盐城/伊宁/银川/重庆）、酿造管理（base佛山/惠州/大理/重庆/西昌/乌鲁木齐/乌苏/银川）、仓储物流管理（base滁州/盐城）、环境健康和安全（base常德/西昌/库尔勒/阿克苏）、采购（base广州）共6大方向\n3. 职能管培生：市场方向、人力资源方向，base广州/成都/昆明\n\n面向对象：毕业时间在2024年7月1日-2026年7月31日的海内外本科或硕士毕业生\n\n我们提供：行业Top薪酬、年终奖金、六险一金、带薪年假、年度体检；女性友好、福利酒水、Happy Hour、生日派对、节日福利；导师带教、集团内职业发展机会、丰富学习资源、轮岗\n内推码：DS5Q2Zyt\n投递链接：https://app.mokahr.com/m/campus_apply/carlsberg/37541?recommendCode=DS5Q2Zyt&hash=%23%2Fjobs#/jobs\n\n嘉士伯2026届校园招聘：558609014",
