      "note": "腾讯音乐2026届校园招聘正式启动\n\n关于我们：腾讯音乐娱乐集团是中国在线音乐娱乐服务开拓者，提供在线音乐和以音乐为核心的社交娱乐两大服务。目前拥有目前国内市场知名的移动音乐产品及长音频平台: QQ 音乐、酷狗音乐、酷我音乐、全民K歌和懒人听书。\n\n招聘岗位：技术类，产品类，设计类，内容类，专业类，市场类\n\n网申提醒：1. 腾讯音乐招聘独立于腾讯集团，可同时分别投递\n2. 感兴趣的业务线可选择3个，提交简历后不可修改\n3. 每位同学只可投递一个岗位，若未在流程中均可修改岗位\n\n投递链接：join.tencentmusic.com/campus\n\n内推码：DS2HLOSV（使用内推码投递，如有任何疑问或流程上的问题，欢迎随时联系）",
