      "searchText": "2026届春招内推\n学而思\n面授主讲（素养教育/国际语言/彼芯托管/竞赛教练多赛道可选）\n\n覆盖全国40+城教学中心，北上广深/新一线/省会城市任选！\n教培\n26届秋招提前批\ndsxpprha\n面授主讲（素养教育/国际语言/彼芯托管/竞赛教练多赛道可选）\n26届秋招提前批\n覆盖全国40+城教学中心，北上广深/新一线/省会城市任选！\n学而思\ndsxpprha\n【学而思2026届校招-提前批火热开启！🔥】\n\n🌟 菁英招募：\n✅ 面向对象：23-26届毕业生均可投递\n✅ 专业不限，教育热忱者优先\n✅ 早鸟专属：提前锁定offer，享受专属培养通道（暑期新教师成长营）\n\n🎯 核心岗位：\n✨ 面授主讲（素养教育/国际语言/彼芯托管/竞赛教练多赛道可选）\n\n🌍 工作地点：\n覆盖全国40+城教学中心，北上广深/新一线/省会城市任选！\n💎 超燃福利包：\n▫💰 行业top薪资架构：12-30w年薪起+4-6次/年调薪机会\n▫🎓 百万级培训体系：新教师成长营\n▫🛡 福利保障： 六险一金+年度体检+带薪年假+带薪病假\n▫🎁 惊喜加成：节日限定礼盒、校区零食角、主题团建、定制周边...\n🚀 极速通道：https://app.mokahr.com/m/campus_apply/tal/148080?recommendcode=dsxpprha&hash=%23%2fjobs\n内推码：dsxpprha（优先处理特权)（输入即享免简历筛选特权）\n📌 面试流程：简历初筛→试讲→新教师成长营→offer洽谈\n\n早投递早收获，让我们在这个夏天，共同书写教育的新篇章！📚✨\nhttps://app.mokahr.com/m/campus_apply/tal/148080?recommendcode=dsxpprha&hash=%23%2fjobshttps://app.mokahr.com/m/campus_apply/tal/148080?recommendcode=dsxpprha&hash=%23%2fjobs\n教培"
