      "note": "招聘岗位\n猎头实习生（可转正）\n📍Base地：北京/上海/苏州/武汉等\n\n岗位职责\n1、与各行业知名客户企业合作，收集客户委托的职位信息，分析并搜寻合适的人才;\n2、根据职位要求，熟知目标候选人画像，访寻到目标候选人并建立联系;\n3、精准地向候选人传递职位信息，了解候选人的职业发展需求和求职动机;\n4、与海内外中高端人才长期保持互动，分析人才与客户公司岗位的匹配度并评估竞争优劣势:\n5、研究行业发展动向，收集人才信息，日常维护并及时更新公司招聘系统人才资源库。\n\n岗位亮点\n🎯抗 AI 替代 ： 高端招聘需深度洞察人性与建立信任，AI 难以企及的独特价值！\n🌐参与发展 ： 助力企业匹配高端人才，推动产业升级与经济发展，成为助力国家发展的参与者！\"\n🚀快速成长 ： FMC 1v1自身Leader带教，体系化成长课程 ，小白变能手！\n🔥资源丰富： 接触多行业多职能岗位，人脉拓宽，多元职业发展！\n🎁氛围超赞： 扁平化管理，伙伴友爱互助，一起并肩作战！\n✨转正保障： 优秀实习生毕业优先转正，晋升通道公平开放！\n\n\n任职要求\n1、本科及以上学历，专业不限；2026届应届生优先。\n2、思路清晰，逻辑成熟，拥有良好的沟通协调能力与服务意识；\n3、结果导向，有良好的学习能力和抗压能力，热爱挑战与自我成长，能适应快节奏的工作方式；\n4、实习时间：尽快入职，工作日每周三天及以上，实长三个月起步；期望\n长期实习，有转正意向同学优先。\n\n面试流程：简历投递—初筛—电话沟通—HR评估—业务面试—发放offer—入职。",
