      "note": "薪资高于大厂 | 杭州睿琪软件26届秋招提前批招聘开启\n\n关于我们：杭州睿琪软件有限公司成立于2009年，在计算机视觉和自然语言理解领域积累深厚，是垂直领域行业领先+国内应用出海Top10。我们拥有超2亿用户，专注于用人工智能技术把生活变得更美好。旗下拥有数款用户数上亿并快速增长的移动应用。\n\n秋招提前批招聘岗位：大模型算法、产品经理、用户增长、用户研究、HRBP、知识产权、UX设计师、视频创意设计师（专业不限，海外教育背景优先）\n\n我们提供：高于大厂的薪资回报（综合年薪：算法岗位80W-150W，产品类岗位40-60W，优秀者上不设限）、实习薪资：600元—2000元/天、年终奖2-8个月、全额五险一金、7-15天带薪年假、利润分享机制\n\n工作地点：杭州市滨江区\n\n内推链接：https://jsj.top/f/eJDHcv",
