      "note": "【智元机器人 2026 届校园招聘正式启动！与未来共舞，让创新落地】\n\n🌟 这里有你能参与的硬核方向\n\n仿真开发：搭建具身智能仿真工具，让机器人在虚拟世界中完成传感器渲染、物理交互的 “预演”；\n具身算法：从 Agent 框架搭建到灵巧手操作，用强化学习、大语言模型解锁机器人的 “决策脑” 与 “灵活手”；\n智能交互：开发语音 SDK，让机器人听懂指令、高效回应，打造自然流畅的人机对话体验；\n数据智能：通过分析挖掘驱动业务优化，构建数据闭环工具链，为机器人进化注入 “数据燃料”；\n全栈研发：从感知、规划到控制，全方位参与机器人系统的算法设计与落地，实现 “感知 - 决策 - 执行” 闭环；\n结构与框架：设计机器人的 “骨骼” 与 “神经中枢”，让机械与智能完美融合……\n\n🚀 加入我们，你将获得\n\n接触前沿技术的一手资源：在 Isaac Sim、MuJoCo 等仿真平台上实践，探索 LLM 与机器人操作的结合，追踪触觉反馈、多模态策略等尖端领域；\n跨团队协作的宝贵经验：与算法、工程、测试团队紧密配合，推动技术从实验室走向真实场景；\n快速成长的空间：无论是实习还是正式岗位，都能深度参与项目核心环节，在解决实际问题中积累硬实力。\n\n📍 岗位地点：上海、北京、深圳（按需选择，多地机会等你挑）\n📮 内推通道：https://agirobot.jobs.feishu.cn/s/j9xTJdvptHs\n✨ 内推福利：使用内推码【BYYYWNU】，简历优先筛选，更快锁定面试机会！\n\n在智元，每一行代码都可能让机器人更聪明，每一次调试都在推动智能的边界。2026 届的你，准备好和我们一起，让机器人真正走进生活、改变世界了吗？点击投递，未来从此刻开始",
